#include "fedspatial/figure1_fixture.hpp"
#include "fedspatial/gpu_context.hpp"
#include "fedspatial/nworker_15k_figure1_config.hpp"
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <iomanip>
#include <iostream>
namespace fs=std::filesystem; using namespace fedspatial;
namespace {
void gates(){for(const char* n:{"FEDSPATIAL_MIXED_TRACE_TILED_ACTION","FEDSPATIAL_MIXED_CONTRACTIONS_TILED","FEDSPATIAL_THETA_FIRST_TILED","FEDSPATIAL_THETA_HESSIAN_AA_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_AR_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_RR_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_Q_W_TILED"})setenv(n,"1",1);}
GlobalParameters initial(){Matrix g(5,1),mu(400,1),s(400,400);const double x[]={-1,2,3,-2,1};for(int i=0;i<5;++i)g(i,0)=x[i];return{g,mu,s,.25,1.,.11,3};}
struct R{DeviceDeltaThetaEvaluation full;DeviceDeltaThetaThetaHessianReduction h;};
R run(GpuContext& c,const WorkerInput&w,const Matrix&k,const GlobalParameters&p,bool second,bool q,bool q_base_reuse=false,bool q_super=false,bool second_batched=false){setenv("FEDSPATIAL_THETA_HESSIAN_SECOND_LOG_TILED",second?"1":"0",1);setenv("FEDSPATIAL_THETA_HESSIAN_Q_PANEL_TILED",q?"1":"0",1);setenv("FEDSPATIAL_THETA_HESSIAN_Q_BASE_REUSE",q_base_reuse?"1":"0",1);setenv("FEDSPATIAL_THETA_HESSIAN_Q_SUPERPANEL",q_super?"1":"0",1);setenv("FEDSPATIAL_THETA_SECOND_TRIPLE_BATCHED",second_batched?"1":"0",1);R r; r.full=compute_device_delta_theta_local(c,w,k,p);r.h=compute_device_delta_theta_theta_hessian_reduction_streamed(c,w,k,p);return r;}
void compare(const char*tag,const R&a,const R&b){double ma=0,mr=0;int slot=-1;auto add=[&](double x,double y,int s){double d=std::abs(x-y),r=d/std::max({1.,std::abs(x),std::abs(y)});if(d>ma){ma=d;mr=r;slot=s;}};add(a.full.summary.objective,b.full.summary.objective,0);for(int i=0;i<3;++i)add(a.full.summary.gradient[i],b.full.summary.gradient[i],1+i);for(int i=0;i<9;++i)add(a.full.summary.hessian[i],b.full.summary.hessian[i],4+i);std::cout<<tag<<" RAW13_MAX_ABS="<<ma<<" MAX_REL="<<mr<<" SLOT="<<slot;for(int e=0;e<3;++e){double t=0.;for(int q=0;q<3;++q)t=std::max(t,std::abs(a.h.terms[e][q]-b.h.terms[e][q]));std::cout<<" HPAIR"<<e<<"_TERM_MAX_ABS="<<t;}std::cout<<'\n';}
}
int main(int argc,char**argv){try{if(argc!=2&&argc!=3)throw std::runtime_error("usage: fixture_leaf [--q-base-only|--q-super-only|--second-batched-only]");const bool q_base_only=argc==3&&std::string(argv[2])=="--q-base-only";const bool q_super_only=argc==3&&std::string(argv[2])=="--q-super-only";const bool second_batched_only=argc==3&&std::string(argv[2])=="--second-batched-only";if(argc==3&&!q_base_only&&!q_super_only&&!second_batched_only)throw std::runtime_error("unknown mode");gates();setenv("CUDA_VISIBLE_DEVICES",NWorker15kFigure1Config::gv100_uuid_0,1);Figure1Fixture f;if(!load_figure1_python_fixture(argv[1],&f))throw std::runtime_error("fixture load");auto w=partition_figure1_fixture(f,2);auto p=initial();for(int id=0;id<2;++id){GpuContext c(0);std::cout<<std::setprecision(17)<<"WORKER="<<id<<'\n';if(q_base_only){auto baseline=run(c,w[id],f.knots,p,true,true,false);auto candidate=run(c,w[id],f.knots,p,true,true,true);compare("Q_BASE_REUSE",baseline,candidate);auto repeat=run(c,w[id],f.knots,p,true,true,true);std::cout<<"Q_BASE_REUSE_BYTE_REPEAT="<<(std::memcmp(&candidate.full.summary,&repeat.full.summary,sizeof(candidate.full.summary))==0?"PASS":"FAIL")<<'\n';continue;}if(q_super_only){auto baseline=run(c,w[id],f.knots,p,true,true,true,false);auto candidate=run(c,w[id],f.knots,p,true,true,true,true);compare("Q_SUPERPANEL",baseline,candidate);auto repeat=run(c,w[id],f.knots,p,true,true,true,true);std::cout<<"Q_SUPERPANEL_BYTE_REPEAT="<<(std::memcmp(&candidate.full.summary,&repeat.full.summary,sizeof(candidate.full.summary))==0?"PASS":"FAIL")<<'\n';continue;}if(second_batched_only){auto baseline=run(c,w[id],f.knots,p,true,true,true,true,false);auto candidate=run(c,w[id],f.knots,p,true,true,true,true,true);compare("SECOND_TRIPLE_BATCHED",baseline,candidate);auto repeat=run(c,w[id],f.knots,p,true,true,true,true,true);std::cout<<"SECOND_TRIPLE_BATCHED_BYTE_REPEAT="<<(std::memcmp(&candidate.full.summary,&repeat.full.summary,sizeof(candidate.full.summary))==0?"PASS":"FAIL")<<'\n';continue;}auto scalar=run(c,w[id],f.knots,p,false,false);auto second=run(c,w[id],f.knots,p,true,false);auto q=run(c,w[id],f.knots,p,false,true);auto both=run(c,w[id],f.knots,p,true,true);compare("SECOND_ONLY",scalar,second);compare("Q_ONLY",scalar,q);compare("BOTH",scalar,both);auto repeat=run(c,w[id],f.knots,p,true,true);std::cout<<"BOTH_BYTE_REPEAT="<<(std::memcmp(&both.full.summary,&repeat.full.summary,sizeof(both.full.summary))==0?"PASS":"FAIL")<<'\n';}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
